        left.Child=new ScrollViewer{Content=nav,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,HorizontalContentAlignment=HorizontalAlignment.Stretch};left.Background=Brush.Parse("#F1F1F1");Put(layout,left,0);Put(layout,MakeSplitter(true),1);
        var center=new Grid{RowDefinitions=new("Auto,*,Auto"),Margin=new Thickness(20,18)};var bar=new Grid{ColumnDefinitions=new("*,Auto,Auto")};Put(bar,heading,0);Put(bar,B("建议",()=>{showSuggestions=!showSuggestions;RefreshRows();}),1);Put(bar,B("⋯",()=>{var l=store.Get("list",view);if(l!=null||Smart.Any(x=>x.Id==view))ListEditor(l,view);}),2);center.Children.Add(bar);var scroll=new ScrollViewer{Content=rows,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,HorizontalContentAlignment=HorizontalAlignment.Stretch,Margin=new Thickness(0,15,0,8)};Grid.SetRow(scroll,1);center.Children.Add(scroll);var addbar=new Grid{ColumnDefinitions=new("*,Auto")};Put(addbar,add,0);Put(addbar,B("添加",AddTask),1);add.KeyDown+=(_,e)=>{if(e.Key==Key.Enter){AddTask();e.Handled=true;}};Grid.SetRow(addbar,2);center.Children.Add(addbar);centerLayers.Children.Add(listBackground);centerLayers.Children.Add(center);centerHost.Child=centerLayers;centerHost.ClipToBounds=true;Put(layout,centerHost,2);Put(layout,MakeSplitter(false),3);
