    private static void Put(Grid g,Control c,int col){Grid.SetColumn(c,col);g.Children.Add(c);}
    private Button B(string title,Action action){var b=new Button{Content=new TextBlock{Text=title,TextWrapping=TextWrapping.Wrap},Tag=title,Padding=new Thickness(10,7),HorizontalAlignment=HorizontalAlignment.Stretch,HorizontalContentAlignment=HorizontalAlignment.Left,Background=Brushes.Transparent,BorderThickness=new Thickness(0)};if(title is "保存" or "连接工作区" or "添加" or "Microsoft 登录并授权导入"){b.Background=new SolidColorBrush(Accent);b.Foreground=Readable(Accent);}else if(title is "○" or "✓" or "★" or "☆"){b.Foreground=new SolidColorBrush(Dark?Mix(Accent,Colors.White,.35):Mix(Accent,Colors.Black,.28));}b.Click+=(_,_)=>action();return b;}
    private static TextBlock T(string text,double size=14)=>new(){Text=text,FontSize=size,TextWrapping=TextWrapping.Wrap,VerticalAlignment=VerticalAlignment.Center};
    private static TextBox Box(string? val,string hint,Action<string>? change=null){var b=new TextBox{Text=val,Watermark=hint};if(change!=null)b.LostFocus+=(_,_)=>{if((b.Text??"")!=(val??""))change(b.Text??"");};return b;}
    private Border Tile(Control c)=>new(){HorizontalAlignment=HorizontalAlignment.Stretch,Background=SurfaceBrush(),CornerRadius=new CornerRadius(5),Padding=new Thickness(8),Child=c};
    private void Select(string id){view=id;selected="";query="";search.Text="";showSuggestions=false;showSettings=false;if(Bounds.Width<760)navShown=false;Refresh();}
    private void Refresh(){detailFooter.Child=null;detailFooter.IsVisible=false;ApplyTheme();RefreshNav();RefreshRows();ApplyListAppearance();if(showSettings)Settings();else Details();Resize();Status();ApplyTextSizes();}
    private void RefreshNav(){nav.Children.Clear();foreach(var (id,label) in Smart){var row=B(label+"   "+store.Tasks(id).Count(t=>Store.IsAttachmentView(id)||!Store.Bool(t,"completed")),()=>Select(id));if(id==view&&query.Length==0){row.Foreground=new SolidColorBrush(Accent);row.BorderBrush=new SolidColorBrush(Accent);row.BorderThickness=new Thickness(3,0,0,0);}nav.Children.Add(row);}nav.Children.Add(new Separator());var lists=store.All("list").ToList();foreach(var l in lists.Where(x=>Store.Str(x,"groupId")==""||store.Get("group",Store.Str(x,"groupId"))==null))nav.Children.Add(B("☷  "+Store.Str(l,"title"),()=>Select(l.Id)));foreach(var g in store.All("group")){nav.Children.Add(B("▣  "+Store.Str(g,"title"),()=>GroupEditor(g)));foreach(var l in lists.Where(x=>Store.Str(x,"groupId")==g.Id))nav.Children.Add(B("     ☷  "+Store.Str(l,"title"),()=>Select(l.Id)));}nav.Children.Add(B("＋ 新建清单",()=>ListEditor(null)));nav.Children.Add(B("＋ 新建分组",()=>GroupEditor(null)));}
    private void RefreshRows(){heading.Text=query!=""?"搜索结果":Smart.FirstOrDefault(x=>x.Id==view).Label??Store.Str(store.Get("list",view),"title","任务");if(view=="day")heading.Text+="  "+DateTime.Today.ToString("M月d日");rows.Children.Clear();var tasks=store.SortTasks(store.Tasks(view,query),query.Length>0?"search":view).ToArray();if(showSuggestions&&view=="day"){rows.Children.Add(T("建议"));foreach(var t in store.Tasks("all").Where(x=>!Store.Bool(x,"completed")&&Store.Str(x,"myDay")!=Store.Today()).Take(30))rows.Children.Add(B("＋ "+Store.Str(t,"title"),()=>{store.Edit("task",t.Id,new(){["myDay"]=Store.Today()});Refresh();}));}foreach(var t in tasks.Where(x=>!Store.Bool(x,"completed")))rows.Children.Add(TaskRow(t));var done=tasks.Where(x=>Store.Bool(x,"completed")).ToArray();if(done.Length>0){var list=new StackPanel{Spacing=4};foreach(var t in done)list.Children.Add(TaskRow(t));var completedGroup=new Expander{Header="已完成 "+done.Length,IsExpanded=true,Content=list,Padding=new Thickness(0),BorderThickness=new Thickness(0),Background=Brushes.Transparent,HorizontalAlignment=HorizontalAlignment.Stretch,HorizontalContentAlignment=HorizontalAlignment.Stretch};completedGroup.Resources["ExpanderContentDownBorderThickness"]=new Thickness(0);rows.Children.Add(completedGroup);}if(tasks.Length==0)rows.Children.Add(new TextBlock{Text="暂时没有任务",HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,80),FontSize=20});ApplyTextSizes();}
    private Control TaskRow(Record t){var g=new Grid{ColumnDefinitions=new("Auto,*,Auto")};Put(g,B(Store.Bool(t,"completed")?"✓":"○",()=>{store.Complete(t,!Store.Bool(t,"completed"));Refresh();}),0);var body=new StackPanel();var title=T(Store.Str(t,"title"));if(Store.Bool(t,"completed"))title.TextDecorations=TextDecorations.Strikethrough;body.Children.Add(title);var att=store.AttachmentStatus(t);body.Children.Add(T(Store.Str(t,"due")+(att.Count>0||att.Pending?"  📎 "+(att.Count>0?att.Count.ToString():"")+(att.Pending?"  待补齐":""):""),11));var b=new Button{Content=body,HorizontalAlignment=HorizontalAlignment.Stretch,HorizontalContentAlignment=HorizontalAlignment.Stretch,BorderThickness=new Thickness(0),Background=Brushes.Transparent};b.Click+=(_,_)=>{selected=t.Id;showSettings=false;Refresh();};Put(g,b,1);Put(g,B(Store.Bool(t,"important")?"★":"☆",()=>{store.Edit("task",t.Id,new(){["important"]=!Store.Bool(t,"important")});Refresh();}),2);return Tile(g);}
    private void AddTask(){var s=add.Text?.Trim();if(string.IsNullOrEmpty(s))return;store.Add(s,store.Get("list",view)!=null?view:"inbox",view);add.Text="";Refresh();}
    private void Patch(string id,string key,JsonNode? value,bool refresh=false){if(!JsonNode.DeepEquals(store.Get("task",id)?.Data[key],value))store.Edit("task",id,new(){[key]=value});if(refresh)Refresh();else{RefreshRows();Status();}}
    private void ConfirmDelete(string id){pane.Children.Add(B("确认删除",()=>{store.DeleteTask(id);selected="";Refresh();}));}
    private void GroupEditor(Record? g){selected="edit";showSettings=false;detailFooter.Child=null;detailFooter.IsVisible=false;pane.Children.Clear();var name=Box(Store.Str(g,"title"),"分组名称");pane.Children.Add(name);pane.Children.Add(B("保存分组",()=>{if(!string.IsNullOrWhiteSpace(name.Text)){store.Edit("group",g?.Id??Store.NewId(),new(){["title"]=name.Text.Trim()});selected="";Refresh();}}));if(g!=null)pane.Children.Add(B("删除分组（保留清单）",()=>{foreach(var l in store.All("list").Where(l=>Store.Str(l,"groupId")==g.Id).ToList())store.Edit("list",l.Id,new(){["groupId"]=null});store.Edit("group",g.Id,new(),true);selected="";Refresh();}));pane.Children.Add(B("取消",()=>{selected="";Refresh();}));Resize();}
    private async Task ImportMicrosoft(){
        if(microsoftImport!=null||store.Busy||accountLogin!=null){Status("请等待当前导入或同步结束");return;}
        var acquire=MicrosoftImport.AcquireToken;if(acquire==null)return;
        using var cts=new CancellationTokenSource();microsoftImport=cts;
        try{Status("请在微软官方浏览器登录并授权");var token=await acquire(MicrosoftImport.ClientId(),cts.Token);var result=await MicrosoftImport.Run(store,token,message=>Status(message),cts.Token);Refresh();Status(result.ToString());if(result.Errors.Count>0){pane.Children.Add(T("部分数据导入失败，可重新授权后重试：",12));foreach(var error in result.Errors.Take(20))pane.Children.Add(T(error,12));}}
        catch(OperationCanceledException){Refresh();Status("已取消导入，已保存的数据保留");}
        catch(Exception e){Refresh();Status("微软导入失败："+e.Message);}
        finally{microsoftImport=null;}
        await Sync();
    }
    private async Task Export(bool csv){try{var p=TopLevel.GetTopLevel(this)?.StorageProvider;if(p==null)return;var f=await p.SaveFilePickerAsync(new(){SuggestedFileName=csv?"HelloTodo.csv":"HelloTodo.json"});if(f==null)return;string s;if(csv){string Q(string x)=>"\""+(x.Length>0&&"=+-@\t\r".Contains(x[0])?"'"+x:x).Replace("\"","\"\"")+"\"";s="\ufefftitle,notes,completed,due\r\n"+string.Join("\r\n",store.All("task").Select(t=>string.Join(",",new[]{"title","notes","completed","due"}.Select(k=>Q(Store.Str(t,k))))));}else{var files=new Dictionary<string,string>();var errors=new List<string>();var workspace=store.Workspace;var records=store.State.Records.Values.ToArray();foreach(var a in records.Where(r=>r.Kind=="attachment"&&!r.Deleted)){try{if(store.Workspace!=workspace)throw new InvalidOperationException("工作区已切换");var data=await store.Download(a.Id);if(store.Workspace!=workspace)throw new InvalidOperationException("工作区已切换");files[a.Id]="data:application/octet-stream;base64,"+Convert.ToBase64String(data);}catch(Exception e){errors.Add(Store.Str(a,"name")+": "+e.Message);}}if(store.Workspace!=workspace)throw new InvalidOperationException("工作区已切换，导出取消");s=JsonSerializer.Serialize(new{format=1,records,files,errors},Store.Json);if(errors.Count>0)Status($"部分附件未导出：{errors.Count}");}await using var stream=await f.OpenWriteAsync();if(stream.CanSeek)stream.SetLength(0);await stream.WriteAsync(Encoding.UTF8.GetBytes(s));Status("导出完成（请查看备份 errors 字段核对附件）");}catch(Exception e){Status(e.Message);}}
    private async Task RestoreBackup(){
        if(store.Busy||microsoftImport!=null){Status("请等待同步或导入完成");return;}
        using var cts=new CancellationTokenSource();microsoftImport=cts;
        try{var provider=TopLevel.GetTopLevel(this)?.StorageProvider;if(provider==null)return;var items=await provider.OpenFilePickerAsync(new(){AllowMultiple=false,FileTypeFilter=new[]{new FilePickerFileType("JSON 备份"){Patterns=new[]{"*.json"}}}});if(items.Count==0)return;
            await using var stream=await items[0].OpenReadAsync();using var ms=new MemoryStream();var buffer=new byte[81920];int n;while((n=await stream.ReadAsync(buffer))>0){if(ms.Length+n>300L*1024*1024)throw new IOException("备份超过 300 MiB，请分批恢复");ms.Write(buffer,0,n);}ms.Position=0;var root=await JsonNode.ParseAsync(ms);if(root?["format"]?.GetValue<int>()!=1||root["records"] is not JsonArray records)throw new IOException("备份格式不正确");
            int restored=0,skipped=0;foreach(var node in records.OfType<JsonObject>()){var kind=node["kind"]?.ToString()??"";var id=node["id"]?.ToString()??"";if(kind is not ("task" or "list" or "group" or "step" or "attachment" or "link")||!System.Text.RegularExpressions.Regex.IsMatch(id,"^[-a-zA-Z0-9_.:]{1,128}$")||node["data"] is not JsonObject data||store.State.Records.ContainsKey(kind+":"+id)){skipped++;continue;}var deleted=node["deleted"]?.GetValue<bool>()==true;if(kind=="attachment"&&!deleted){var encoded=root["files"]?[id]?.ToString()??"";var comma=encoded.IndexOf(',');if(!encoded.StartsWith("data:",StringComparison.Ordinal)||comma<0||!encoded[..comma].EndsWith(";base64",StringComparison.OrdinalIgnoreCase)){skipped++;continue;}byte[] bytes;try{bytes=Convert.FromBase64String(encoded[(comma+1)..]);}catch(FormatException){skipped++;continue;}if(bytes.Length>25*1024*1024){skipped++;continue;}store.PutFile(id,bytes);}store.Edit(kind,id,data,deleted);restored++;}Refresh();Status($"备份恢复：新增 {restored}，跳过 {skipped}");}
        catch(Exception e){Status("恢复失败："+e.Message);}finally{microsoftImport=null;}
    }
    private async Task PickFiles(string task){try{var p=TopLevel.GetTopLevel(this)?.StorageProvider;if(p==null)return;foreach(var f in await p.OpenFilePickerAsync(new(){AllowMultiple=true})){await using var stream=await f.OpenReadAsync();using var ms=new MemoryStream();var buffer=new byte[81920];int n;while((n=await stream.ReadAsync(buffer))>0){if(ms.Length+n>25*1024*1024)throw new IOException("附件最大 25 MiB");ms.Write(buffer,0,n);}var id=Store.NewId();store.PutFile(id,ms.ToArray());store.Edit("attachment",id,new(){["taskId"]=task,["name"]=f.Name,["size"]=ms.Length,["type"]="application/octet-stream"});}Refresh();}catch(Exception e){Status(e.Message);}}
    private async Task SaveAttachment(Record a){try{var data=await store.Download(a.Id);var p=TopLevel.GetTopLevel(this)?.StorageProvider;if(p==null)return;var f=await p.SaveFilePickerAsync(new(){SuggestedFileName=Store.Str(a,"name")});if(f==null)return;await using var s=await f.OpenWriteAsync();if(s.CanSeek)s.SetLength(0);await s.WriteAsync(data);}catch(Exception e){Status(e.Message);}}
    private async Task Sync(){if(store.Cloud==null||store.Busy||microsoftImport!=null||accountLogin!=null)return;try{Status("同步中");await store.Sync();RefreshNav();RefreshRows();ApplyListAppearance();Status("已同步 "+DateTime.Now.ToString("HH:mm:ss"));}catch(Exception e){Status("同步失败："+e.Message);}}
    private void Status(string msg="")=>status.Text=(store.Cloud==null?"本地模式":"云同步")+" · "+store.State.Pending.Count+" 项待同步 "+msg;
    private readonly HashSet<string> reminders=new();private void CheckReminders(){foreach(var t in store.All("task").Where(t=>!Store.Bool(t,"completed")))if(DateTimeOffset.TryParse(Store.Str(t,"reminder"),out var d)&&d<=DateTimeOffset.Now&&d>DateTimeOffset.Now.AddDays(-1)&&reminders.Add(t.Id+":"+d))Status("提醒："+Store.Str(t,"title"));}
}
